// Validate and structure customer data
// PostgreSQL Edition - No Google OAuth required
const data = $input.first().json;

// Required fields (NO Google credentials needed!)
const required = [
  'customer_id', 'owner_name', 'owner_email', 'owner_phone',
  'telegram_credential_name', 'whatsapp_credential_name',
  'openai_api_key'
];

const missing = required.filter(f => !data[f]);
if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Generate unique subdomain from customer name
const subdomain = data.customer_id.toLowerCase().replace(/[^a-z0-9]/g, '-');

return [{
  json: {
    customer_id: data.customer_id,
    subdomain: subdomain,
    domain: `${subdomain}.ergovia-ai.com`,

    owner: {
      name: data.owner_name,
      email: data.owner_email,
      phone: data.owner_phone
    },

    credential_names: {
      telegram: data.telegram_credential_name,
      whatsapp: data.whatsapp_credential_name
    },

    openai_api_key: data.openai_api_key,

    properties: data.properties || [],

    hetzner: {
      server_type: data.server_type || 'cx21',
      location: data.location || 'nbg1',
      image: 'ubuntu-22.04'
    },

    deployment: {
      started_at: new Date().toISOString(),
      current_phase: 0,
      phases: []
    }
  }
}];

const data = $('✅ Phase 0: Validate & Structure').first().json;
const phase1Result = $input.first().json;

data.deployment.phases.push({
  phase: 1,
  name: 'Server Provisioning',
  status: phase1Result.status,
  duration: phase1Result.duration,
  completed_at: new Date().toISOString()
});

data.deployment.current_phase = 2;
data.server = phase1Result.server;

return [{json: data}];

const data = $('Track Phase 1').first().json;
const phase2Result = $input.first().json;

data.deployment.phases.push({
  phase: 2,
  name: 'Server Setup + PostgreSQL + Authelia',
  status: phase2Result.status,
  duration: phase2Result.duration,
  completed_at: new Date().toISOString()
});

data.deployment.current_phase = 3;
data.server.n8n_ready = phase2Result.n8n_ready;
data.server.n8n_url = phase2Result.n8n_url;
data.server.n8n_admin = phase2Result.n8n_credentials;
data.server.n8n_api_key = phase2Result.n8n_api_key;
data.server.authelia_url = phase2Result.authelia_url;

return [{json: data}];

const data = $('Track Phase 2').first().json;
const phase3Result = $input.first().json;

data.deployment.phases.push({
  phase: 3,
  name: 'Database Setup',
  status: phase3Result.status,
  duration: phase3Result.duration,
  completed_at: new Date().toISOString()
});

data.deployment.current_phase = 4;
data.database = phase3Result.database;
data.nocodb_url = phase3Result.nocodb.url;

return [{json: data}];

const data = $('Track Phase 3').first().json;
const phase4Result = $input.first().json;

data.deployment.phases.push({
  phase: 4,
  name: 'Workflow Configuration',
  status: phase4Result.status,
  duration: phase4Result.duration,
  completed_at: new Date().toISOString()
});

data.deployment.current_phase = 5;
data.workflows_configured = phase4Result.workflows_configured;

return [{json: data}];

const data = $('Track Phase 4').first().json;
const phase5Result = $input.first().json;

data.deployment.phases.push({
  phase: 5,
  name: 'Workflow Deployment',
  status: phase5Result.status,
  duration: phase5Result.duration,
  completed_at: new Date().toISOString()
});

data.deployment.current_phase = 6;
data.workflows_deployed = phase5Result.workflows_deployed;

return [{json: data}];

const data = $('Track Phase 5').first().json;
const phase6Result = $input.first().json;

data.deployment.phases.push({
  phase: 6,
  name: 'Customer Notification',
  status: phase6Result.status,
  duration: phase6Result.duration,
  completed_at: new Date().toISOString()
});

const totalDuration = Math.round(
  (new Date() - new Date(data.deployment.started_at)) / 1000
);

return [{
  json: {
    success: true,
    customer_id: data.customer_id,

    access: {
      control_panel: `https://${data.domain}/control-panel`,
      nocodb: data.nocodb_url,
      authelia_protected: true
    },

    database: {
      type: 'PostgreSQL',
      tables_created: 21,
      nocodb_interface: true
    },

    workflows: {
      configured: data.workflows_configured || 24,
      deployed: data.workflows_deployed || 24,
      active: true
    },

    deployment: {
      total_duration_seconds: totalDuration,
      phases_completed: data.deployment.phases.length,
      completed_at: new Date().toISOString()
    },

    message: 'Customer deployment completed successfully. No Google OAuth required!'
  }
}];
